def backfill_verification_status(apps, schema_editor):
    """Before Nov 2026 the Verified badge could be self-granted (any 11 digits passed as a NIN).
    Policy is now admin-approved verification only, so every existing designer who supplied
    NIN/CAC is placed in the admin review queue and the badge is removed until re-approved."""
    VendorProfile = apps.get_model('vendors', 'VendorProfile')
    for vendor in VendorProfile.objects.all():
        has_identity = bool((vendor.nin_number or '').strip() or (vendor.cac_number or '').strip())
        vendor.verification_status = 'PENDING_REVIEW' if has_identity else 'NOT_SUBMITTED'
        vendor.verification_submitted_at = vendor.updated_at if has_identity else None
        vendor.is_verified = False
        vendor.kyc_tier = 'TIER_1_STARTER'
        vendor.save(update_fields=['verification_status', 'verification_submitted_at', 'is_verified', 'kyc_tier'])


